WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) x AS attr_key, attr_value) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, COUNT(*) FILTER (WHERE attr_key = 'device') AS device_rows, MIN(created_at) AS started_at FROM lines GROUP BY DATE_TRUNC('HOUR', created_at)
